package com.glassbox.chess; import com.glassbox.chess.domain.*; import com.glassbox.chess.game.ChessGame; import com.glassbox.chess.rule.*; import com.glassbox.chess.util.FenParser; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; public class RulesTest{@Test void foolsMateIsCheckmate()throws Exception{ChessGame g=new ChessGame();TestMoves.play(g,"f2","f3");TestMoves.play(g,"e7","e5");TestMoves.play(g,"g2","g4");TestMoves.play(g,"d8","h4");assertEquals(GameStatus.CHECKMATE,g.getStatus());}@Test void stalemateIsDetected(){Board b=FenParser.parse("7k/5Q2/6K1/8/8/8/8/8 b - - 0 1");assertEquals(GameStatus.STALEMATE,GameStateEvaluator.evaluate(b));}@Test void pinnedRookCannotExposeKing()throws Exception{Board b=FenParser.parse("4r1k1/8/8/8/8/8/4R3/4K3 w - - 0 1");for(Move m:MoveValidator.getLegalMoves(b,Color.WHITE))if(m.getMovedPiece().getType()==PieceType.ROOK)assertEquals(4,m.getTo().getFile());}}
